27: /**
28:  * Configuration data for the application, potentially built from many sources.
29:  * <p>
30:  * A {@link ConfigData} object allows configuration to be “read” as Java objects.
31:  * The data used to populate the objects is specified when building the configuration data.
32:  * The static methods of this interface can be used to build a configuration data object.
33:  * <pre class="java">{@code
34:  * import com.google.common.collect.ImmutableMap;
35:  * import ratpack.config.ConfigData;
36:  * import ratpack.server.RatpackServer;
37:  * import ratpack.test.http.TestHttpClient;
38:  * import static org.junit.Assert.*;
39:  *
40:  * public class Example {
41:  *   public static class MyAppConfig {
42:  *     private String name;
43:  *
44:  *     public String getName() {
45:  *       return name;
46:  *     }
47:  *   }
48:  *
49:  *   public static void main(String[] args) throws Exception {
50:  *     RatpackServer server = RatpackServer.of(spec -> {
51:  *       ConfigData config = ConfigData.of(d -> d
52:  *         .props(ImmutableMap.of("server.port", "5060", "app.name", "Ratpack"))
53:  *         .sysProps()
54:  *       );
55:  *       spec
56:  *         .serverConfig(config.getServerConfig())
57:  *         .registryOf(r -> r
58:  *           .add(config)
59:  *           .add(config.get("/app", MyAppConfig.class))
60:  *         )
61:  *         .handler(registry ->
62:  *           (ctx) -> ctx.render("Hi, my name is " + ctx.get(MyAppConfig.class).getName())
63:  *         );
64:  *     });
65:  *     server.start();
66:  *
67:  *     assertTrue(server.isRunning());
68:  *     assertEquals(5060, server.getBindPort());
69:  *
70:  *     TestHttpClient httpClient = TestHttpClient.testHttpClient(server);
71:  *     assertEquals("Hi, my name is Ratpack", httpClient.getText());
72:  *
73:  *     server.stop();
74:  *   }
75:  * }
76:  * }</pre>
77:  * <h3>Configuration Reloading</h3>
78:  * <p>
79:  * The created configuration data instance should be added to the server registry (as in the above example).
80:  * This enables automatically reloading the configuration when it changes.
81:  *
82:  * @see ConfigDataSpec
83:  */
84: public interface ConfigData extends ReloadInformant, Service {
85: 
86:   /**
87:    * Begins building a new application configuration using a default object mapper.
88:    *
89:    * @return the new configuration data spec
90:    */
91:   static ConfigDataSpec of() {
92:     return new DefaultConfigDataSpec(ServerEnvironment.env());
93:   }
94: 
95:   static ConfigData of(Action<? super ConfigDataSpec> config) throws Exception {
96:     return config.with(of()).build();
97:   }
98: 
99:   /**
100:    * Begins building a new application configuration using a default object mapper with the supplied modules registered.
101:    *
102:    * @param modules the Jackson modules to register with a default object mapper
103:    * @return the new configuration data spec
104:    */
105:   static ConfigDataSpec of(Module... modules) {
106:     return new DefaultConfigDataSpec(ServerEnvironment.env(), modules);
107:   }
108: 
109:   static ConfigData of(List<Module> modules, Action<? super ConfigDataSpec> config) throws Exception {
110:     return config.with(of(modules.toArray(new Module[modules.size()]))).build();
111:   }
112: 
113:   /**
114:    * Begins building a new application configuration using a specified object mapper.
115:    *
116:    * @param objectMapper the object mapper to use for configuration purposes
117:    * @return the new configuration data spec
118:    */
119:   static ConfigDataSpec of(ObjectMapper objectMapper) {
120:     return new DefaultConfigDataSpec(ServerEnvironment.env(), objectMapper);
121:   }
122: 
123:   static ConfigData of(ObjectMapper objectMapper, Action<? super ConfigDataSpec> config) throws Exception {
124:     return config.with(of(objectMapper)).build();
125:   }
126: 
127:   /**
128:    * Binds a segment of the configuration data to the specified type.
129:    *
130:    * @param pointer a <a href="https://tools.ietf.org/html/rfc6901">JSON Pointer</a> specifying
131:    * the point in the configuration data to bind from
132:    * @param type the class of the type to bind to
133:    * @param <O> the type to bind to
134:    * @return an instance of the specified type with bound configuration data
135:    */
136:   <O> O get(String pointer, Class<O> type);
137: 
138:   /**
139:    * Binds the root of the configuration data to the specified type.
140:    *
141:    * @param type the class of the type to bind to
142:    * @param <O> the type to bind to
143:    * @return an instance of the specified type with bound configuration data
144:    */
145:   default <O> O get(Class<O> type) {
146:     return get(null, type);
147:   }
148: 
149:   default ServerConfig getServerConfig() {
150:     return getServerConfig("/server");
151:   }
152: 
153:   default ServerConfig getServerConfig(String pointer) {
154:     return get(pointer, ServerConfig.class);
155:   }
156: 
157: }
