38:     final AtomicReference<ExecResult<T>> reference = new AtomicReference<>();
39:     final CountDownLatch latch = new CountDownLatch(1);
40: 
41:     controller.getControl().exec()
42:       .onError(throwable -> {
43:         reference.set(new ResultBackedExecResult<>(Result.<T>failure(throwable)));
44:         latch.countDown();
45:       })
