49:           execution.onCleanup(() -> {
50:             if (latch.getCount() > 0) {
51:               reference.set(new CompleteExecResult<>());
52:               latch.countDown();
53:             }
54:           });
55:           Promise<T> promise = func.apply(execution);
56: 
57:           if (promise == null) {
58:             succeed(null);
59:           } else {
60:             promise.then(this::succeed);
61:           }
62:         }
63: 
64:         private void succeed(T t) {
65:           reference.set(t == null ? null : new ResultBackedExecResult<>(Result.success(t)));
66:           latch.countDown();
67:         }
68:       });
