70:       String[] sessionCookiePartitions = serialize(sessionData);
71:       for (int i = 0; i < sessionCookiePartitions.length; i++) {
72:         addSessionCookie(config.getSessionCookieName() + "_" + i, sessionCookiePartitions[i]);
73:       }
74:       for (int i = sessionCookiePartitions.length; i < oldSessionCookiesCount; i++) {
75:         invalidateSessionCookie(config.getSessionCookieName() + "_" + i);
76:       }
77:     });
