100:   private String[] serialize(ByteBuf sessionData) {
101:     if (sessionData == null || sessionData.readableBytes() == 0) {
102:       return new String[0];
103:     }
104: 
105:     ByteBuf encrypted = null;
106:     ByteBuf digest = null;
107: 
108:     try {
109:       encrypted = crypto.encrypt(sessionData, bufferAllocator);
110:       String encryptedBase64 = toBase64(encrypted);
111:       digest = signer.sign(encrypted.resetReaderIndex(), bufferAllocator);
112:       String digestBase64 = toBase64(digest);
113:       String digestedBase64 = encryptedBase64 + SESSION_SEPARATOR + digestBase64;
114:       if (digestedBase64.length() <= config.getMaxSessionCookieSize()) {
115:         return new String[]{digestedBase64};
116:       }
117:       int count = (int) Math.ceil((double) digestedBase64.length() / config.getMaxSessionCookieSize());
118:       String[] partitions = new String[count];
119:       for (int i = 0; i < count; i++) {
120:         int from = i * config.getMaxSessionCookieSize();
121:         int to = Math.min(from + config.getMaxSessionCookieSize(), digestedBase64.length());
122:         partitions[i] = digestedBase64.substring(from, to);
123:       }
124:       return partitions;
125:     } finally {
126:       if (encrypted != null) {
127:         encrypted.release();
128:       }
129:       if (digest != null) {
130:         digest.release();
131:       }
132:     }
133:   }
