135:   private ByteBuf deserialize(Cookie[] sessionCookies) {
136:     if (sessionCookies.length == 0) {
137:       return Unpooled.buffer(0, 0);
138:     }
139:     StringBuilder sessionCookie = new StringBuilder();
140:     for (int i = 0; i < sessionCookies.length; i++) {
141:       sessionCookie.append(sessionCookies[i].value());
142:     }
143:     String[] parts = sessionCookie.toString().split(SESSION_SEPARATOR);
144:     if (parts.length != 2) {
145:       return Unpooled.buffer(0, 0);
146:     }
147:     ByteBuf payload = null;
148:     ByteBuf digest = null;
149:     ByteBuf expectedDigest = null;
150:     ByteBuf decryptedPayload = null;
151:     try {
152:       payload = fromBase64(bufferAllocator, parts[0]);
153:       digest = fromBase64(bufferAllocator, parts[1]);
154:       expectedDigest = signer.sign(payload, bufferAllocator);
155:       if (ByteBufUtil.equals(digest, expectedDigest)) {
156:         decryptedPayload = crypto.decrypt(payload.resetReaderIndex(), bufferAllocator);
157:       } else {
158:         decryptedPayload = Unpooled.buffer(0, 0);
159:       }
160:     } finally {
161:       if (payload != null) {
162:         payload.release();
163:       }
164:       if (digest != null) {
165:         digest.release();
166:       }
167:       if (expectedDigest != null) {
168:         expectedDigest.release();
169:       }
170:     }
171:     return decryptedPayload;
172:   }
