174:   private String toBase64(ByteBuf byteBuf) {
175:     ByteBuf encoded = Base64.encode(byteBuf, false, Base64Dialect.STANDARD);
176:     try {
177:       return encoded.toString(CharsetUtil.ISO_8859_1);
178:     } finally {
179:       encoded.release();
180:     }
181:   }
