183:   private ByteBuf fromBase64(ByteBufAllocator bufferAllocator, String string) {
184:     ByteBuf byteBuf = ByteBufUtil.encodeString(bufferAllocator, CharBuffer.wrap(string), CharsetUtil.ISO_8859_1);
185:     try {
186:       return Base64.decode(byteBuf, Base64Dialect.STANDARD);
187:     } finally {
188:       byteBuf.release();
189:     }
190:   }
