299:   public <T, O> T parse(Parse<T, O> parse) throws ParserException, NoSuchParserException {
300:     String requestContentType = requestConstants.request.getBody().getContentType().getType();
301:     if (requestContentType == null) {
302:       requestContentType = "text/plain";
303:     }
304: 
305:     final String finalRequestContentType = requestContentType;
306:     return getRegistry().first(PARSER_TYPE_TOKEN, new ParserForParsePredicate(parse, requestContentType))
307:       .<T>map(parser -> {
308:         Parser<O> castParser = Types.cast(parser);
309:         try {
310:           return castParser.parse(this, getRequest().getBody(), parse);
311:         } catch (Exception e) {
312:           throw new ParserException(parser, e);
313:         }
314:       })
315:       .orElseThrow(() -> new NoSuchParserException(parse.getType(), parse.getOpts(), finalRequestContentType));
316:   }
