374:   public void error(Throwable throwable) {
375:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
376:     throwable = unpackThrowable(throwable);
377: 
378:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
379:     if (throwableHolder == null) {
380:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
381: 
382:       try {
383:         serverErrorHandler.error(this, throwable);
384:       } catch (Throwable errorHandlerThrowable) {
385:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
386:       }
387:     } else {
388:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
389:     }
390:   }
391: 
392:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
393:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
394:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
395:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
396: 
397:     LOGGER.error(msg);
398: 
399:     Response response = requestConstants.response.status(500);
400:     if (getLaunchConfig().isDevelopment()) {
401:       response.send(msg);
402:     } else {
403:       response.send();
404:     }
405:   }
406: 
407:   private Throwable unpackThrowable(Throwable throwable) {
408:     if (throwable instanceof UndeclaredThrowableException) {
409:       return throwable.getCause();
410:     } else {
411:       return throwable;
412:     }
413:   }
