71:       public String getExistingId() {
72:         return getCookieSessionId();
73:       }
74: 
75:       @Override
76:       public String regen() {
77:         String existingId = getExistingId();
78:         if (existingId != null) {
79:           sessionConfig.getSessionListener().sessionTerminated(existingId);
80:         }
81:         return assignId();
82: 
83:       }
84: 
