86:       public void terminate() {
87:         String existingId = getExistingId();
88:         if (existingId == null) {
89:           throw new IllegalStateException("Cannot terminate inactive session");
90:         }
91:         sessionConfig.getSessionListener().sessionTerminated(existingId);
92:         setCookie("", new Date(0));
93:       }
94:     };
