98:     if (assignedCookieId != null) {
99:       return assignedCookieId;
100:     }
101: 
102:     String cookieSessionId = getCookieSessionId();
103:     if (cookieSessionId != null) {
104:       return cookieSessionId;
105:     }
106: 
107:     assignedCookieId = assignId();
108:     return assignedCookieId;
109:   }
110: 
111:   private String assignId() {
112:     String id = sessionConfig.getIdGenerator().generateSessionId(request);
113:     int expiryMins = sessionConfig.getCookieExpiryMins();
114:     if (expiryMins > 0) {
115:       Calendar expires = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
116:       expires.add(Calendar.MINUTE, expiryMins);
117:       setCookie(id, expires.getTime());
118:     } else {
119:       setCookie(id, null);
120:     }
121: 
122:     sessionConfig.getSessionListener().sessionInitiated(id);
123:     return id;
124:   }
125: 
126:   private void setCookie(String value, Date expires) {
127:     if (alreadySetCookie) {
128:       throw new IllegalStateException("Cannot set cookie twice for the one request");
129:     }
130:     alreadySetCookie = true;
131:     StringBuilder setCookieValue = new StringBuilder(COOKIE_NAME).append("=").append(value)
132:         .append(";").append("path=").append(sessionConfig.getCookiePath());
133: 
134:     String cookieDomain = sessionConfig.getCookieDomain();
135:     if (!cookieDomain.equals("localhost")) {
136:       setCookieValue.append(";domain=.").append(cookieDomain);
