31: /**
32:  * A promise for a single value.
33:  * <p>
34:  * A promise is a representation of a value which will become available later.
35:  * Methods such as {@link #map(Function)}, {@link #flatMap(Function)}, {@link #cache()} etc.) allow a pipeline of “operations” to be specified,
36:  * that the value will travel through as it becomes available.
37:  * Such operations are implemented via the {@link #transform(Function)} method.
38:  * Each operation returns a new promise object, not the original promise object.
39:  * <p>
40:  * To create a promise, use the {@link Promise#async(Upstream)} method (or one of the variants such as {@link Promise#sync(Factory)}.
41:  * To test code that uses promises, use the {@link ratpack.test.exec.ExecHarness}.
42:  * <p>
43:  * The promise is not “activated” until the {@link #then(Action)} method is called.
44:  * This method terminates the pipeline, and receives the final value.
45:  * <p>
46:  * Promise objects are multi use.
47:  * Every promise pipeline has a value producing function at its start.
48:  * Activating a promise (i.e. calling {@link #then(Action)}) invokes the function.
49:  * The {@link #cache()} operation can be used to change this behaviour.
50:  *
51:  * @param <T> the type of promised value
52:  */
53: @SuppressWarnings("JavadocReference")
54: public interface Promise<T> {
55: 
56:   /**
57:    * Creates a promise for value that will be produced asynchronously.
58:    * <p>
59:    * The {@link Upstream#connect(Downstream)} method of the given upstream will be invoked every time the value is requested.
60:    * This method should propagate the value (or error) to the given downstream object when it is available.
61:    *
62:    * <pre class="java">{@code
63:    * import ratpack.exec.Promise;
64:    * import ratpack.test.exec.ExecHarness;
65:    *
66:    * import static org.junit.Assert.assertEquals;
67:    *
68:    * public class Example {
69:    *   public static void main(String[] args) throws Exception {
70:    *     String value = ExecHarness.yieldSingle(e ->
71:    *       Promise.<String>async(down ->
72:    *         new Thread(() -> {
73:    *           down.success("foo");
74:    *         }).start()
75:    *       )
76:    *     ).getValueOrThrow();
77:    *
78:    *     assertEquals(value, "foo");
79:    *   }
80:    * }
81:    * }</pre>
82:    *
83:    * @param upstream the producer of the value
84:    * @param <T> the type of promised value
85:    * @return a promise for the asynchronously created value
86:    * @see Upstream
87:    * @see #sync(Factory)
88:    * @see #value(Object)
89:    * @see #error(Throwable)
90:    * @since 1.3
91:    */
92:   static <T> Promise<T> async(Upstream<T> upstream) {
93:     return new DefaultPromise<>(DefaultExecution.upstream(upstream));
94:   }
95: 
96:   /**
97:    * Creates a promise for value, synchronously, produced by the given factory.
98:    * <p>
99:    * The given factory will be invoked every time that the value is requested.
100:    * If the factory throws an exception, the promise will convey that exception.
101:    *
102:    * <pre class="java">{@code
103:    * import ratpack.exec.Promise;
104:    * import ratpack.test.exec.ExecHarness;
105:    *
106:    * import static org.junit.Assert.assertEquals;
107:    *
108:    * public class Example {
109:    *   public static void main(String[] args) throws Exception {
110:    *     String value = ExecHarness.yieldSingle(e ->
111:    *       Promise.sync(() -> "foo")
112:    *     ).getValueOrThrow();
113:    *
114:    *     assertEquals(value, "foo");
115:    *   }
116:    * }
117:    * }</pre>
118:    *
119:    * <p>
120:    * This method is often used to when a method needs to return a promise, but can produce its value synchronously.
121:    *
122:    * @param factory the producer of the value
123:    * @param <T> the type of promised value
124:    * @return a promise for the result of the factory
125:    * @see #async(Upstream)
126:    * @see #value(Object)
127:    * @see #error(Throwable)
128:    * @since 1.3
129:    */
130:   static <T> Promise<T> sync(Factory<T> factory) {
131:     return async(down -> {
132:       T t;
133:       try {
134:         t = factory.create();
135:       } catch (Exception e) {
136:         down.error(e);
137:         return;
138:       }
139:       down.success(t);
140:     });
141:   }
142: 
143:   /**
144:    * Creates a promise for the given item.
145:    * <p>
146:    * The given item will be used every time that the value is requested.
147:    *
148:    * <pre class="java">{@code
149:    * import ratpack.exec.Promise;
150:    * import ratpack.test.exec.ExecHarness;
151:    *
152:    * import static org.junit.Assert.assertEquals;
153:    *
154:    * public class Example {
155:    *   public static void main(String[] args) throws Exception {
156:    *     String value = ExecHarness.yieldSingle(e ->
157:    *       Promise.value("foo")
158:    *     ).getValueOrThrow();
159:    *
160:    *     assertEquals(value, "foo");
161:    *   }
162:    * }
163:    * }</pre>
164:    *
165:    * @param t the promised value
166:    * @param <T> the type of promised value
167:    * @return a promise for the given item
168:    * @see #async(Upstream)
169:    * @see #sync(Factory)
170:    * @see #error(Throwable)
171:    */
172:   static <T> Promise<T> value(T t) {
173:     return async(down -> down.success(t));
174:   }
