210:   /**
211:    * Deprecated.
212:    *
213:    * @param upstream the producer of the value
214:    * @param <T> the type of promised value
215:    * @return a promise for the asynchronously created value
216:    * @deprecated replaced by {@link #async(Upstream)}
217:    */
218:   @Deprecated
219:   static <T> Promise<T> of(Upstream<T> upstream) {
