256:   /**
257:    * Apply a custom transform to this promise.
258:    * <p>
259:    * This method is the basis for the standard operations of this interface, such as {@link #map(Function)}.
260:    * The following is a non generic implementation of a map that converts the value to upper case.
261:    * <pre class="java">{@code
262:    * import ratpack.test.exec.ExecHarness;
263:    * import ratpack.exec.ExecResult;
264:    * import ratpack.exec.Promise;
265:    *
266:    * import static org.junit.Assert.assertEquals;
267:    *
268:    * public class Example {
269:    *   public static void main(String... args) throws Exception {
270:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
271:    *       Promise.value("foo")
272:    *         .transform(up -> down ->
273:    *           up.connect(down.<String>onSuccess(value -> {
274:    *             try {
275:    *               down.success(value.toUpperCase());
276:    *             } catch (Throwable e) {
277:    *               down.error(e);
278:    *             }
279:    *           }))
280:    *         )
281:    *     );
282:    *
283:    *     assertEquals("FOO", result.getValue());
284:    *   }
285:    * }
286:    * }</pre>
287:    * <p>
288:    * The “upstreamTransformer” function takes an upstream data source, and returns another upstream that wraps it.
289:    * It is typical for the returned upstream to invoke the {@link Upstream#connect(Downstream)} method of the given upstream during its connect method.
290:    * <p>
291:    * For more examples of transform implementations, please see the implementations of the methods of this interface.
292:    *
293:    * @param upstreamTransformer a function that returns a new upstream, typically wrapping the given upstream argument
294:    * @param <O> the type of item emitted by the transformed upstream
295:    * @return a new promise
296:    */
297:   <O> Promise<O> transform(Function<? super Upstream<? extends T>, ? extends Upstream<O>> upstreamTransformer);
298: 
299:   /**
300:    * Specifies the action to take if the an error occurs trying to produce the promised value, that the given predicate applies to.
301:    * <p>
302:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
303:    * by the action added to the suppressed exceptions list.
304:    *
305:    * @param predicate the predicate to test against the error
306:    * @param errorHandler the action to take if an error occurs
307:    * @return A promise for the successful result
308:    * @since 1.1
309:    */
310:   default Promise<T> onError(Predicate<? super Throwable> predicate, Action<? super Throwable> errorHandler) {
311:     return transform(up -> down ->
312:       up.connect(down.onError(throwable -> {
313:         if (predicate.apply(throwable)) {
314:           try {
315:             errorHandler.execute(throwable);
316:           } catch (Throwable e) {
317:             if (e != throwable) {
318:               e.addSuppressed(throwable);
319:             }
320:             down.error(e);
321:             return;
322:           }
323:           down.complete();
324:         } else {
325:           down.error(throwable);
326:         }
327:       }))
328:     );
329:   }
330: 
331:   /**
332:    * Specifies the action to take if the an error of the given type occurs trying to produce the promised value.
333:    *
334:    * <pre class="java">{@code
335:    * import ratpack.http.TypedData;
336:    * import ratpack.test.embed.EmbeddedApp;
337:    *
338:    * import static org.junit.Assert.assertEquals;
339:    *
340:    * public class Example {
341:    *   public static void main(String... args) throws Exception {
342:    *     EmbeddedApp.fromHandler(ctx ->
343:    *         ctx.getRequest().getBody()
344:    *           .map(TypedData::getText)
345:    *           .map(t -> {
346:    *             if (t.equals("1")) {
347:    *               throw new IllegalArgumentException("validation error!");
348:    *             } else {
349:    *               throw new RuntimeException("some other error!");
350:    *             }
351:    *           })
352:    *           .onError(IllegalArgumentException.class, e -> ctx.render("the value is invalid"))
353:    *           .onError(e -> ctx.render("unknown error: " + e.getMessage()))
354:    *           .then(t -> ctx.render("ok"))
355:    *     ).test(httpClient -> {
356:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("0")).postText(), "unknown error: some other error!");
357:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("1")).postText(), "the value is invalid");
358:    *     });
359:    *   }
360:    * }
361:    * }</pre>
362:    * <p>
363:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
364:    * by the action added to the suppressed exceptions list.
365:    *
366:    * @param errorType the type of exception to handle with the given action
367:    * @param errorHandler the action to take if an error occurs
368:    * @param <E> the type of exception to handle with the given action
369:    * @return A promise for the successful result
370:    * @since 1.1
371:    */
372:   default <E extends Throwable> Promise<T> onError(Class<E> errorType, Action<? super E> errorHandler) {
373:     return onError(errorType::isInstance, t -> errorHandler.execute(errorType.cast(t)));
374:   }
375: 
376:   /**
377:    * Specifies the action to take if the an error occurs trying to produce the promised value.
378:    * <p>
379:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
380:    * by the action added to the suppressed exceptions list.
381:    *
382:    * @param errorHandler the action to take if an error occurs
383:    * @return A promise for the successful result
384:    */
385:   default Promise<T> onError(Action<? super Throwable> errorHandler) {
386:     return onError(Predicate.TRUE, errorHandler);
387:   }
