389:   /**
390:    * Consume the promised value as a {@link Result}.
391:    * <p>
392:    * This method is an alternative to {@link #then(Action)} and {@link #onError(Action)}.
393:    *
394:    * @param resultHandler the consumer of the result
395:    */
396:   default void result(Action<? super Result<T>> resultHandler) {
397:     onError(t -> resultHandler.execute(Result.<T>error(t))).then(v -> resultHandler.execute(Result.success(v)));
398:   }
