400:   /**
401:    * Transforms the promised value by applying the given function to it.
402:    * <pre class="java">{@code
403:    * import ratpack.test.exec.ExecHarness;
404:    * import ratpack.exec.ExecResult;
405:    * import ratpack.exec.Promise;
406:    *
407:    * import static org.junit.Assert.assertEquals;
408:    *
409:    * public class Example {
410:    *   public static void main(String... args) throws Exception {
411:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
412:    *         Promise.value("foo")
413:    *           .map(String::toUpperCase)
414:    *           .map(s -> s + "-BAR")
415:    *     );
416:    *
417:    *     assertEquals("FOO-BAR", result.getValue());
418:    *   }
419:    * }
420:    * }</pre>
421:    *
422:    * @param transformer the transformation to apply to the promised value
423:    * @param <O> the type of the transformed object
424:    * @return a promise for the transformed value
425:    */
426:   default <O> Promise<O> map(Function<? super T, ? extends O> transformer) {
427:     return transform(up -> down -> up.connect(
428:       down.<T>onSuccess(value -> {
429:         try {
430:           O apply = transformer.apply(value);
431:           down.success(apply);
432:         } catch (Throwable e) {
433:           down.error(e);
434:         }
435:       })
436:       )
437:     );
438:   }
