481:   /**
482:    * Executes the provided, potentially asynchronous, {@link Action} with the promised value as input.
483:    * <p>
484:    * This method can be used when needing to perform an action with the promised value, without substituting the promised value.
485:    * That is, the exact same object provided to the given action will be propagated downstream.
486:    * <p>
487:    * The given action is executed within an {@link Operation}, allowing it to perform asynchronous work.
488:    *
489:    * <pre class="java">{@code
490:    * import ratpack.test.exec.ExecHarness;
491:    * import ratpack.exec.ExecResult;
492:    * import ratpack.exec.Promise;
493:    *
494:    * import com.google.common.collect.Lists;
495:    *
496:    * import java.util.concurrent.TimeUnit;
497:    * import java.util.Arrays;
498:    * import java.util.List;
499:    *
500:    * import static org.junit.Assert.assertEquals;
501:    *
502:    * public class Example {
503:    *   public static void main(String... args) throws Exception {
504:    *     List<String> events = Lists.newLinkedList();
505:    *     ExecHarness.runSingle(c ->
506:    *       Promise.value("foo")
507:    *        .next(v ->
508:    *          Promise.value(v) // may be async
509:    *            .map(String::toUpperCase)
510:    *            .then(events::add)
511:    *        )
512:    *        .then(events::add)
513:    *     );
514:    *     assertEquals(Arrays.asList("FOO", "foo"), events);
515:    *   }
516:    * }
517:    * }</pre>
518:    *
519:    * @param action the action to execute with the promised value
520:    * @return a promise for the original value
521:    * @see #nextOp(Function)
522:    * @since 1.1
523:    */
524:   default Promise<T> next(@NonBlocking Action<? super T> action) {
525:     return nextOp(v ->
526:       Operation.of(() ->
527:         action.execute(v)
528:       )
529:     );
530:   }
