533:   /**
534:    * Executes the operation returned by the given function.
535:    * <p>
536:    * This method can be used when needing to perform an operation returned by another object, based on the promised value.
537:    *
538:    * <pre class="java">{@code
539:    * import ratpack.test.exec.ExecHarness;
540:    * import ratpack.exec.ExecResult;
541:    * import ratpack.exec.Promise;
542:    * import ratpack.exec.Operation;
543:    *
544:    * import com.google.common.collect.Lists;
545:    *
546:    * import java.util.concurrent.TimeUnit;
547:    * import java.util.Arrays;
548:    * import java.util.List;
549:    *
550:    * import static org.junit.Assert.assertEquals;
551:    *
552:    * public class Example {
553:    *
554:    *   public static class CaseService {
555:    *     public Operation toUpper(String value, List<String> values) {
556:    *       return Operation.of(() -> values.add(value.toUpperCase()));
557:    *     }
558:    *   }
559:    *
560:    *   public static void main(String... args) throws Exception {
561:    *     CaseService service = new CaseService();
562:    *     List<String> events = Lists.newLinkedList();
563:    *
564:    *     ExecHarness.runSingle(c ->
565:    *       Promise.value("foo")
566:    *        .nextOp(v -> service.toUpper(v, events))
567:    *        .then(events::add)
568:    *     );
569:    *
570:    *     assertEquals(Arrays.asList("FOO", "foo"), events);
571:    *   }
572:    * }
573:    * }</pre>
574:    *
575:    * @param function a function that returns an operation that acts on the promised value
576:    * @return a promise for the original value
577:    * @see #next(Action)
578:    * @since 1.1
579:    */
580:   default Promise<T> nextOp(Function<? super T, ? extends Operation> function) {
581:     return transform(up -> down -> up.connect(
582:       down.<T>onSuccess(value ->
583:         function.apply(value)
584:           .onError(down::error)
585:           .then(() ->
586:             down.success(value)
587:           )
588:       )
589:       )
590:     );
591:   }
