1124:    *     ExecHarness.runSingle(c -> {
1125:    *       Throwable error = new Exception("bang!");
1126:    *       Promise<Object> cached = Promise.error(error).cache();
1127:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
1128:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
1129:    *       cached.onError(t -> assertTrue(t == error)).then(i -> assertTrue("not called", false));
