702:       up.connect(down.onError(throwable -> {
703:         try {
704:           T transformed = function.apply(throwable);
705:           down.success(transformed);
706:         } catch (Throwable t) {
707:           down.error(t);
708:         }
709:       }))
710:     );
711:   }
