32: public class DefaultBackground implements Background {
33: 
34:   private final ExecutorService foregroundExecutor;
35:   private final ListeningExecutorService backgroundExecutor;
36:   private final ContextStorage contextStorage;
37: 
38:   public DefaultBackground(ExecutorService foregroundExecutor, ListeningExecutorService backgroundExecutor, ContextStorage contextStorage) {
39:     this.foregroundExecutor = foregroundExecutor;
40:     this.backgroundExecutor = backgroundExecutor;
41:     this.contextStorage = contextStorage;
42:   }
