37: /**
38:  * An extension module that provides support for Thymeleaf templating engine.
39:  * <p>
40:  * To use it one has to register the module and then render {@link ratpack.thymeleaf.Template} instances.
41:  * Instances of {@code Template} can be created using one of the
42:  * {@link ratpack.thymeleaf.Template#thymeleafTemplate(java.util.Map, String, String)}
43:  * static methods.
44:  * <p>
45:  * By default templates are looked up in the {@code thymeleaf} directory of the application root with a {@code .html} suffix.
46:  * So {@code thymeleafTemplate("my/template/path")} maps to {@code thymeleaf/my/template/path.html} in the application root directory.
47:  * This can be configured using {@link #setTemplatesPrefix(String)} and {@link #setTemplatesSuffix(String)} as well as
48:  * {@code other.thymeleaf.templatesPrefix} and {@code other.thymeleaf.templatesSuffix} configuration properties.
49:  * <p>
50:  * Response content type can be manually specified, i.e. {@code thymeleafTemplate("template", model, "text/html")} if
51:  * not specified will default to {@code text/html}.
52:  * <pre class="java">{@code
53:  * import ratpack.guice.Guice;
54:  * import ratpack.test.embed.BaseDirBuilder;
55:  * import ratpack.test.embed.EmbeddedApp;
56:  * import ratpack.thymeleaf.ThymeleafModule;
57:  *
58:  * import java.nio.file.Path;
59:  *
60:  * import static ratpack.thymeleaf.Template.thymeleafTemplate;
61:  * import static org.junit.Assert.*;
62:  *
63:  * public class Example {
64:  *
65:  *   public static void main(String... args) throws Exception {
66:  *     Path baseDir = BaseDirBuilder.tmpDir().build(builder ->
67:  *         builder.file("thymeleaf/myTemplate.html", "<span th:text=\"${key}\"/>")
68:  *     );
69:  *     EmbeddedApp.fromHandlerFactory(baseDir, registry ->
70:  *       Guice.builder(registry)
71:  *           .bindings(b -> b.add(new ThymeleafModule()))
72:  *           .build(chain -> chain
73:  *               .get(ctx -> ctx.render(thymeleafTemplate("myTemplate", m -> m.put("key", "Hello Ratpack!"))))
74:  *           )
75:  *     ).test(httpClient -> {
76:  *       assertEquals("<span>Hello Ratpack!</span>", httpClient.getText());
77:  *     });
78:  *   }
79:  * }
80:  * }</pre>
81:  * <p>
82:  * To register dialects, use Guice Multibindings to bind an implementation of {@code IDialect} in a module.
