358:   public void lastModified(Date date, Runnable runnable) {
359:     Date ifModifiedSinceHeader = requestConstants.request.getHeaders().getDate(IF_MODIFIED_SINCE);
360:     long lastModifiedSecs = date.getTime() / 1000;
361: 
362:     if (ifModifiedSinceHeader != null) {
363:       long time = ifModifiedSinceHeader.getTime();
364:       long ifModifiedSinceSecs = time / 1000;
365: 
366:       if (lastModifiedSecs == ifModifiedSinceSecs) {
367:         requestConstants.response.status(NOT_MODIFIED.code()).send();
368:         return;
369:       }
370:     }
371: 
372:     requestConstants.response.getHeaders().setDate(HttpHeaderConstants.LAST_MODIFIED, date);
373:     runnable.run();
374:   }
