376:   public void error(Throwable throwable) {
377:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
378:     throwable = unpackThrowable(throwable);
379: 
380:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
381:     if (throwableHolder == null) {
382:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
383: 
384:       try {
385:         serverErrorHandler.error(this, throwable);
386:       } catch (Throwable errorHandlerThrowable) {
387:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
388:       }
389:     } else {
390:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
391:     }
392:   }
393: 
394:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
395:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
396:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
397:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
398: 
399:     LOGGER.error(msg);
400: 
401:     Response response = requestConstants.response.status(500);
402:     if (getServerConfig().isDevelopment()) {
403:       response.send(msg);
404:     } else {
405:       response.send();
406:     }
407:   }
