41: public class DefaultExecController implements ExecController {
42: 
43:   private static final ThreadLocal<ExecController> THREAD_BINDING = new ThreadLocal<>();
44: 
45:   private final static Logger LOGGER = LoggerFactory.getLogger(DefaultExecController.class);
46: 
47:   private final ThreadLocal<Execution> executionHolder = new ThreadLocal<>();
48: 
49:   private final ListeningScheduledExecutorService computeExecutor;
50:   private final ListeningExecutorService blockingExecutor;
51:   private final EventLoopGroup eventLoopGroup;
52:   private final ExecControl control;
53:   private final int numThreads;
54: 
55:   public DefaultExecController(int numThreads) {
56:     this.numThreads = numThreads;
57:     this.eventLoopGroup = new NioEventLoopGroup(numThreads, new ExecControllerBindingThreadFactory("ratpack-compute", Thread.MAX_PRIORITY));
58:     this.computeExecutor = MoreExecutors.listeningDecorator(eventLoopGroup);
59:     this.blockingExecutor = MoreExecutors.listeningDecorator(Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory("ratpack-blocking", Thread.NORM_PRIORITY)));
60:     this.control = new FactoryBackedExecControl();
61:   }
62: 
63:   public static Optional<ExecController> getThreadBoundController() {
64:     return Optional.fromNullable(THREAD_BINDING.get());
65:   }
66: 
67:   public void close() {
68:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
69:     blockingExecutor.shutdown();
70:   }
71: 
72:   @Override
73:   public Execution getExecution() throws ExecutionException {
74:     Execution execution = executionHolder.get();
75:     if (execution == null) {
76:       throw new ExecutionException("No execution is bound to the current thread (are you calling this from a blocking operation or a manual created thread?)");
77:     } else {
78:       return execution;
79:     }
80:   }
81: 
82:   @Override
83:   public ListeningScheduledExecutorService getExecutor() {
84:     return computeExecutor;
85:   }
86: 
87:   @Override
88:   public EventLoopGroup getEventLoopGroup() {
89:     return eventLoopGroup;
90:   }
91: 
92:   @Override
93:   public void start(final Action<? super ratpack.exec.Execution> action) {
94:     if (!isManagedThread() || executionHolder.get() != null) {
95:       computeExecutor.submit(new Runnable() {
96:         @Override
97:         public void run() {
98:           start(action);
99:         }
100:       });
101:     } else {
102:       new Execution(action);
103:     }
104:   }
105: 
106:   private class FactoryBackedExecControl implements ExecControl {
107: 
108:     private final Factory<Execution> executionFactory = new Factory<Execution>() {
109:       @Override
110:       public Execution create() {
111:         return getExecution();
112:       }
113:     };
114: 
115:     @Override
116:     public <T> Promise<T> blocking(final Callable<T> blockingOperation) {
117:       return promise(new Action<Fulfiller<? super T>>() {
118:         @Override
119:         public void execute(final Fulfiller<? super T> fulfiller) throws Exception {
120:           final Execution execution = getExecution();
121:           ListenableFuture<T> future = blockingExecutor.submit(new BlockingOperation(execution));
122:           Futures.addCallback(future, new ComputeResume(fulfiller), computeExecutor);
123:         }
124: 
125:         class BlockingOperation implements Callable<T> {
126:           private final Execution execution;
127:           private Exception exception;
128:           private T result;
129: 
130:           public BlockingOperation(Execution execution) {
131:             this.execution = execution;
132:           }
133: 
134:           @Override
135:           public T call() throws Exception {
136:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<Execution>() {
137:               @Override
138:               public void execute(Execution execution) throws Exception {
139:                 try {
140:                   result = blockingOperation.call();
141:                 } catch (Exception e) {
142:                   exception = e;
143:                 }
144:               }
145:             });
146: 
147:             if (exception != null) {
148:               throw exception;
149:             } else {
150:               return result;
151:             }
152:           }
153:         }
154: 
155:         class ComputeResume implements FutureCallback<T> {
156:           private final Fulfiller<? super T> fulfiller;
157: 
158:           public ComputeResume(Fulfiller<? super T> fulfiller) {
159:             this.fulfiller = fulfiller;
160:           }
161: 
162:           @Override
163:           public void onSuccess(final T result) {
164:             fulfiller.success(result);
165:           }
166: 
167:           @SuppressWarnings("NullableProblems")
168:           @Override
169:           public void onFailure(final Throwable t) {
170:             fulfiller.error(t);
171:           }
172:         }
173:       });
174: 
175:     }
176: 
177:     @Override
178:     public <T> Promise<T> promise(Action<? super Fulfiller<T>> action) {
179:       return new DefaultPromise<>(executionFactory, action);
180:     }
181: 
182:     @Override
183:     public void fork(Action<? super ratpack.exec.Execution> action) {
184:       start(action);
185:     }
186: 
187:     @Override
188:     public <T> void subscribe(Publisher<T> publisher, final Subscriber<T> subscriber) {
189:       publisher.subscribe(new Subscriber<T>() {
190:         final Execution execution = getExecution();
191: 
192:         @Override
193:         public void onSubscribe(final Subscription subscription) {
194:           this.execution.continueVia(new Runnable() {
195:             @Override
196:             public void run() {
197:               subscriber.onSubscribe(subscription);
198:             }
199:           });
200:         }
201: 
202:         @Override
203:         public void onNext(final T element) {
204:           this.execution.continueExecutionAndWait(new Action<ratpack.exec.Execution>() {
205:             @Override
206:             public void execute(ratpack.exec.Execution execution) throws Exception {
207:               subscriber.onNext(element);
208:             }
209:           });
210:         }
211: 
212:         @Override
213:         public void onComplete() {
214:           this.execution.joinExecutionEnd(new Action<ratpack.exec.Execution>() {
215:             @Override
216:             public void execute(ratpack.exec.Execution execution) throws Exception {
217:               subscriber.onComplete();
218:             }
219:           });
220:         }
221: 
222:         @Override
223:         public void onError(final Throwable cause) {
224:           this.execution.joinExecutionEnd(new Action<ratpack.exec.Execution>() {
225:             @Override
226:             public void execute(ratpack.exec.Execution execution) throws Exception {
227:               subscriber.onError(cause);
228:             }
229:           });
230:         }
231:       });
232:     }
233:   }
