235:   public class Execution extends SimpleMutableRegistry implements ratpack.exec.Execution {
236:     private final List<ExecInterceptor> interceptors = new LinkedList<>();
237:     private final Deque<Runnable> segments = new ConcurrentLinkedDeque<>();
238:     private final Queue<Runnable> onCompletes = new ConcurrentLinkedQueue<>();
239: 
240:     private Action<? super Throwable> errorHandler = new Action<Throwable>() {
241:       @Override
242:       public void execute(Throwable throwable) throws Exception {
243:         throw ExceptionUtils.toException(throwable);
244:       }
245:     };
246: 
247:     private final AtomicBoolean active = new AtomicBoolean();
248:     private boolean waiting;
249:     private boolean done;
250: 
251:     public Execution(Action<? super ratpack.exec.Execution> action) {
252:       segments.addLast(new UserCodeSegment(action));
253:       tryDrain();
254:     }
255: 
256:     @Override
257:     public <T> Promise<T> blocking(final Callable<T> operation) {
258:       return control.blocking(operation);
259:     }
260: 
261: 
262:     @Override
263:     public <T> Promise<T> promise(final Action<? super Fulfiller<T>> action) {
264:       return control.promise(action);
265:     }
266: 
267:     @Override
268:     public void fork(Action<? super ratpack.exec.Execution> action) {
269:       control.fork(action);
270:     }
271: 
272:     @Override
273:     public <T> void subscribe(Publisher<T> publisher, Subscriber<T> subscriber) {
274:       control.subscribe(publisher, subscriber);
275:     }
276: 
277:     @Override
278:     public void setErrorHandler(Action<? super Throwable> errorHandler) {
279:       this.errorHandler = errorHandler;
280:     }
281: 
282:     @Override
283:     public void addInterceptor(ExecInterceptor execInterceptor, Action<? super ratpack.exec.Execution> continuation) throws Exception {
284:       interceptors.add(execInterceptor);
285:       intercept(ExecInterceptor.ExecType.COMPUTE, Collections.singletonList(execInterceptor), continuation);
286:     }
287: 
288:     @Override
289:     public ExecController getController() {
290:       return DefaultExecController.this;
291:     }
292: 
293: 
294:     public void join(final Action<? super ratpack.exec.Execution> action) {
295:       segments.addFirst(new UserCodeSegment(action));
296:       waiting = false;
297:       tryDrain();
298:     }
