17: package ratpack.exec.internal;
18: 
19: import io.netty.util.internal.PlatformDependent;
20: import ratpack.exec.*;
21: import ratpack.func.Predicate;
22: 
23: import java.util.Queue;
24: import java.util.concurrent.atomic.AtomicBoolean;
25: import java.util.concurrent.atomic.AtomicReference;
26: 
27: public class CachingUpstream<T> implements Upstream<T> {
28: 
29:   private Upstream<? extends T> upstream;
30: 
31:   private final AtomicReference<ExecResult<? extends T>> resultRef = new AtomicReference<>();
32:   private final Predicate<? super ExecResult<T>> predicate;
33: 
34:   private final AtomicBoolean pending = new AtomicBoolean();
35:   private final AtomicBoolean draining = new AtomicBoolean();
36:   private final Queue<Downstream<? super T>> waiting = PlatformDependent.newMpscQueue();
37: 
38:   public CachingUpstream(Upstream<? extends T> upstream, Predicate<? super ExecResult<T>> predicate) {
39:     this.upstream = upstream;
40:     this.predicate = predicate;
41:   }
42: 
43:   private void tryDrain() {
44:     if (draining.compareAndSet(false, true)) {
45:       try {
46:         ExecResult<? extends T> result = this.resultRef.get();
47:         if (result == null) {
48:           if (pending.compareAndSet(false, true)) {
49:             Downstream<? super T> downstream = waiting.poll();
50:             if (downstream == null) {
51:               pending.set(false);
52:             } else {
53:               try {
54:                 yield(downstream);
55:               } catch (Throwable e) {
56:                 receiveResult(downstream, ExecResult.of(Result.error(e)));
57:               }
58:             }
59:           }
60:         } else {
61:           Downstream<? super T> downstream = waiting.poll();
62:           while (downstream != null) {
63:             downstream.accept(result);
64:             downstream = waiting.poll();
65:           }
66:         }
67:       } finally {
68:         draining.set(false);
69:       }
70:     }
71: 
72:     if (!waiting.isEmpty() && (resultRef.get() != null || !pending.get())) {
73:       tryDrain();
74:     }
75:   }
76: 
77:   private void yield(final Downstream<? super T> downstream) throws Exception {
78:     upstream.connect(new Downstream<T>() {
79:       public void error(Throwable throwable) {
80:         receiveResult(downstream, ExecResult.of(Result.<T>error(throwable)));
81:       }
82: 
83:       @Override
84:       public void success(T value) {
85:         receiveResult(downstream, ExecResult.of(Result.success(value)));
86:       }
87: 
88:       @Override
89:       public void complete() {
90:         receiveResult(downstream, CompleteExecResult.get());
91:       }
92:     });
93:   }
94: 
95:   @Override
96:   public void connect(Downstream<? super T> downstream) throws Exception {
97:     ExecResult<? extends T> result = this.resultRef.get();
98:     if (result == null) {
99:       Promise.<T>async(d -> {
100:         waiting.add(d);
101:         tryDrain();
102:       }).result(downstream::accept);
103:     } else {
104:       downstream.accept(result);
105:     }
106:   }
107: 
108:   private void receiveResult(Downstream<? super T> downstream, ExecResult<T> result) {
109:     boolean shouldCache = false;
110:     try {
111:       shouldCache = predicate.apply(result);
112:     } catch (Throwable e) {
113:       if (result.isError()) {
114:         //noinspection ThrowableResultOfMethodCallIgnored
115:         result.getThrowable().addSuppressed(e);
116:       } else {
117:         result = ExecResult.of(Result.error(e));
118:       }
119:     }
120: 
121:     if (shouldCache) {
122:       this.resultRef.set(result);
123:       this.upstream = null; // release
124:     } else {
125:       pending.set(false);
126:     }
127: 
128:     downstream.accept(result);
129: 
130:     tryDrain();
131:   }
132: 
133: }
