39:   private final AtomicReference<Result<T>> result = new AtomicReference<>();
40: 
41:   public CachingPromise(Action<? super Fulfiller<T>> action, Factory<ExecutionBacking> executionProvider, Action<? super Throwable> errorHandler) {
42:     this.action = action;
43:     this.executionSupplier = executionProvider;
