50:   }
51: 
52:   @Override
53:   public void then(Action<? super T> then) {
54:     newPromise().then(then);
55:   }
56: 
57:   private void tryDrain() {
58:     if (draining.compareAndSet(false, true)) {
59:       try {
60:         Result<T> result = this.result.get();
61: 
62:         Fulfiller<T> poll = waiting.poll();
63:         while (poll != null) {
64:           fulfill(result, poll);
65:           poll = waiting.poll();
66:         }
67:       } finally {
68:         draining.set(false);
69:       }
70:     }
71:     if (!waiting.isEmpty()) {
72:       tryDrain();
73:     }
74:   }
75: 
76:   private DefaultSuccessPromise<T> newPromise() {
77:     return new DefaultSuccessPromise<>(executionSupplier, new Fulfillment(), errorHandler);
78:   }
79: 
80:   @Override
81:   public <O> Promise<O> map(Function<? super T, ? extends O> transformer) {
82:     return newPromise().map(transformer);
83:   }
84: 
85:   @Override
