110:   private class Fulfillment implements Action<Fulfiller<T>> {
111:     @Override
112:     public void execute(Fulfiller<T> fulfiller) throws Exception {
113:       if (fired.compareAndSet(false, true)) {
114:         try {
115:           action.execute(new Fulfiller<T>() {
116:             @Override
117:             public void error(Throwable throwable) {
118:               result.set(DefaultResult.<T>failure(throwable));
119:               tryDrain();
120:             }
121: 
122:             @Override
123:             public void success(T value) {
124:               result.set(DefaultResult.success(value));
125:               tryDrain();
126:             }
127:           });
128:         } catch (Throwable throwable) {
129:           result.set(DefaultResult.<T>failure(throwable));
130:           tryDrain();
131:         }
132:       }
133: 
134:       Result<T> resultValue = result.get();
135:       if (resultValue == null) {
136:         waiting.add(fulfiller);
137:         if (result.get() != null) {
138:           tryDrain();
139:         }
140:       } else {
141:         fulfill(resultValue, fulfiller);
142:       }
143:     }
144:   }
145: 
146:   void fulfill(Result<T> result, Fulfiller<? super T> fulfiller) {
147:     if (result.isFailure()) {
