75:     minimalResponse.headers().set(response.headers());
76:     ChannelFuture writeFuture = channel.writeAndFlush(minimalResponse);
77: 
78:     writeFuture.addListener(new ChannelFutureListener() {
79:       public void operationComplete(ChannelFuture future) throws Exception {
80:         if (!future.isSuccess()) {
81:           closeQuietly(fileChannel);
82:           channel.close();
83:         }
84:       }
85:     });
86: 
