562:   private static class Startup implements Service {
563: 
564:     private final Config config;
565:     private final Injector injector;
566: 
567:     @Inject
568:     public Startup(Config config, Injector injector) {
569:       this.config = config;
570:       this.injector = injector;
571:     }
572: 
573:     @Override
574:     public void onStart(StartEvent event) throws Exception {
575:       config.getJmx().ifPresent(jmx -> {
576:         if (jmx.isEnabled()) {
577:           injector.getInstance(JmxReporter.class).start();
578:         }
579:       });
580: 
581:       config.getConsole().ifPresent(console -> {
582:         if (console.isEnabled()) {
583:           injector.getInstance(ConsoleReporter.class).start(console.getReporterInterval().getSeconds(), SECONDS);
584:         }
585:       });
586: 
587:       config.getCsv().ifPresent(csv -> {
588:         if (csv.isEnabled()) {
589:           injector.getInstance(CsvReporter.class).start(csv.getReporterInterval().getSeconds(), SECONDS);
590:         }
591:       });
592: 
593:       if (config.isJvmMetrics()) {
594:         final MetricRegistry metricRegistry = injector.getInstance(MetricRegistry.class);
595:         metricRegistry.registerAll(new GarbageCollectorMetricSet());
596:         metricRegistry.registerAll(new ThreadStatesGaugeSet());
597:         metricRegistry.registerAll(new MemoryUsageGaugeSet());
598:       }
599:     }
600:   }
