27: /**
28:  * A container of modules, used for specifying which modules to back an application with.
29:  * <p>
30:  * Ratpack adds the special {@link HandlerDecoratingModule} interface that modules can implement if they want
31:  * to influence the handler “chain”.
32:  * <p>
33:  * The order that modules are registered in is important.
34:  * Modules registered later can override the bindings of modules registered prior.
35:  * This can be useful for overriding default implementation bindings.
36:  * <p>
37:  * Some modules have properties/methods that can be used to configure their bindings.
38:  * This method can be used to retrieve such modules and configure them.
39:  * The modules have have already been registered “upstream”.
40:  * <pre class="tested">
41:  * import ratpack.guice.*;
42:  * import ratpack.util.*;
43:  * import com.google.inject.AbstractModule;
44:  *
45:  * class MyService {
46:  *   private final String value;
47:  *   public MyService(String value) {
48:  *     this.value = value;
49:  *   }
50:  * }
51:  *
52:  * class MyModule extends AbstractModule {
53:  *   public String serviceValue;
54:  *
55:  *   protected void configure() {
56:  *     bind(MyService.class).toInstance(new MyService(serviceValue));
57:  *   }
58:  * }
59:  *
60:  * class ModuleAction implements Action&lt;ModuleRegistry&gt; {
61:  *   public void execute(ModuleRegistry modules) {
62:  *     // MyModule has been added by some other action that executed against this registry…
63:  *
64:  *     modules.get(MyModule.class).serviceValue = "foo";
65:  *   }
66:  * }
67:  * </pre>
68:  *
69:  * @see Guice#handler(ratpack.launch.LaunchConfig, ratpack.util.Action, ratpack.util.Action)
70:  * @see HandlerDecoratingModule
71:  */
72: public interface ModuleRegistry extends MutableRegistry<Module> {
73: 
74:   /**
75:    * The launch config for the application the module registry is for.
76:    *
77:    * @return the launch config for the application the module registry is for.
78:    */
79:   LaunchConfig getLaunchConfig();
80: 
81:   void bind(Class<?> type);
82: 
83:   <T> void bind(Class<T> publicType, Class<? extends T> implType);
84: 
85:   <T> void bind(Class<? super T> publicType, T instance);
86: 
87:   <T> void bind(T instance);
88: 
89:   <T> void provider(Class<T> publicType, Class<? extends Provider<? extends T>> providerType);
90: 
