64:   private String buildBlockingTimerTag(String requestPath, String requestMethod) {
65:     String tagName = requestPath.equals("") ? "root" : requestPath.replace("/", ".");
66: 
67:     if (config.getRequestMetricGroups() != null) {
68:       for (Map.Entry<String, String> metricGrouping : config.getRequestMetricGroups().entrySet()) {
69:         if (requestPath.matches(metricGrouping.getValue())) {
70:           tagName = metricGrouping.getKey();
71:           break;
72:         }
73:       }
74:     }
