124:    *
125:    * Value: {@value}
126:    *
127:    * @see #HealthCheckHandler(String, int)
128:    */
129:   public static final String DEFAULT_NAME_TOKEN = "name";
130:   private static final TypeToken<ratpack.health.HealthCheck> HEALTH_CHECK_TYPE_TOKEN = TypeToken.of(ratpack.health.HealthCheck.class);
131: 
