234:   private void handleByName(Context context, String name) throws Exception {
235:     Optional<ratpack.health.HealthCheck> healthCheck = context.first(HEALTH_CHECK_TYPE_TOKEN, it -> it.getName().equals(name) ? it : null);
236: 
237:     if (!healthCheck.isPresent()) {
238:       context.clientError(404);
239:       return;
240:     }
241:     try {
242:       Promise<ratpack.health.HealthCheck.Result> promise = healthCheck.get().check(context.getExecution().getControl());
243:       promise.onError(throwable -> {
244:         context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), ratpack.health.HealthCheck.Result.unhealthy(throwable))));
245:       }).then(r -> {
246:         context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), r)));
247:       });
248:     } catch (Exception ex) {
249:       context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), ratpack.health.HealthCheck.Result.unhealthy(ex))));
250:     }
251:   }
