48:     return new AsyncResultHandler<T>() {
49:       @Override
50:       public void handle(AsyncResult<T> event) {
51:         if (event.failed()) {
52:           ErrorHandler.this.handle(new ErroredHttpServerRequest(request, event.exception));
53:         } else {
54:           handler.handle(event.result);
55:         }
56:       }
57:     };
