61:     DecodedStackTrace decodedStackTrace = decodeStackTrace(exception);
62:     Map<Object, Object> model = new LinkedHashMap<Object, Object>();
63:     model.put("title", exception.getClass().getName());
64:     model.put("message", exception.getMessage());
65:     model.put("stacktrace", decodedStackTrace.html);
66: 
67:     Map<Object, Object> metadata = new LinkedHashMap<Object, Object>();
68:     metadata.put("Request Method", request.method.toUpperCase());
69:     metadata.put("Request URL", request.uri);
70:     metadata.put("Exception Type", exception.getClass().getName());
71:     metadata.put("Exception Location", decodedStackTrace.rootCause.getFileName() + ", line " + decodedStackTrace.rootCause.getLineNumber());
72:     model.put("metadata", metadata);
73: 
74:     templateCompiler.compileErrorTemplate(model, handler);
