88:     StringBuilder html = new StringBuilder();
89:     html.append(exception.toString()).append("\n");
90:     StackTraceElement rootCause = null;
91: 
92:     for (StackTraceElement ste : exception.getStackTrace()) {
93:       if (!StackTraceUtils.isApplicationClass(ste.getClassName())) {
94:         html.append("<span class='stack-thirdparty'>        at ").append(ste.toString()).append("</span>\n");
95:       } else {
96:         html.append("        at ").append(ste.toString()).append("\n");
