130:           @Override
131:           public T call() throws Exception {
132:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<Execution>() {
133:               @Override
134:               public void execute(Execution execution) throws Exception {
135:                 try {
