134:           @Override
135:           public T call() throws Exception {
136:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<ExecutionBacking>() {
137:               @Override
138:               public void execute(ExecutionBacking execution) throws Exception {
139:                 try {
140:                   result = blockingOperation.call();
141:                 } catch (Exception e) {
142:                   exception = e;
143:                 }
144:               }
145:             });
146: 
147:             if (exception != null) {
148:               throw exception;
149:             } else {
150:               return result;
