392:     public void intercept(final ExecInterceptor.ExecType execType, final List<ExecInterceptor> interceptors, final Action<? super ExecutionBacking> action) throws Exception {
393:       new InterceptedOperation(execType, interceptors) {
394:         @Override
395:         protected void performOperation() throws Exception {
396:           action.execute(ExecutionBacking.this);
397:         }
398:       }.run();
399:     }
