401:     /**
402:      * An execution segment that executes “user code” (i.e. not execution management infrastructure)
403:      */
404:     private class UserCodeSegment implements Runnable {
405:       private final Action<? super ratpack.exec.ExecutionBacking> action;
406: 
407:       public UserCodeSegment(Action<? super ratpack.exec.ExecutionBacking> action) {
408:         this.action = action;
409:       }
410: 
411:       @Override
412:       public void run() {
413:         try {
414:           try {
415:             intercept(ExecInterceptor.ExecType.COMPUTE, interceptors, action);
416:           } catch (ExecutionSegmentTerminationError e) {
417:             throw e.getCause();
418:           }
419:         } catch (final Throwable e) {
420:           segments.clear();
421:           segments.addFirst(new Runnable() {
422:             @Override
423:             public void run() {
424:               try {
425:                 errorHandler.execute(e);
426:               } catch (final Throwable e) {
427:                 segments.addFirst(new UserCodeSegment(new Action<ratpack.exec.ExecutionBacking>() {
428:                   @Override
429:                   public void execute(ratpack.exec.ExecutionBacking execution) throws Exception {
430:                     throw e;
431:                   }
432:                 }));
433:               }
434:             }
435:           });
436:         }
437:       }
438:     }
439:   }
