19: import io.netty.handler.codec.http.HttpHeaders;
20: import org.ratpackframework.handling.Exchange;
21: import org.ratpackframework.handling.ByAcceptsResponder;
22: import org.ratpackframework.http.internal.MimeParse;
23: 
24: import java.util.*;
25: 
26: public class DefaultByAcceptsResponder implements ByAcceptsResponder {
27: 
28:   private final Map<String, Runnable> map = new LinkedHashMap<String, Runnable>(3);
29:   private String first;
30:   private final Exchange exchange;
31: 
32:   public DefaultByAcceptsResponder(Exchange exchange) {
33:     this.exchange = exchange;
34:   }
35: 
36:   public ByAcceptsResponder type(String mimeType, Runnable runnable) {
37:     if (mimeType == null) {
38:       throw new IllegalArgumentException("mimeType cannot be null");
39:     }
40: 
41:     String trimmed = mimeType.trim();
42:     if (trimmed.isEmpty()) {
43:       throw new IllegalArgumentException("mimeType cannot be a blank string");
44:     }
45: 
46:     if (first == null) {
47:       first = trimmed;
48:     }
49:     map.put(trimmed, runnable);
50:     return this;
51:   }
52: 
53:   public void send() {
54:     if (first == null) {
55:       exchange.clientError(406);
56:       return;
57:     }
58: 
59:     List<String> types = new ArrayList<String>(map.keySet());
60:     Collections.reverse(types);
61:     String winner = first;
62: 
63:     String acceptHeader = exchange.getRequest().getHeader(HttpHeaders.Names.ACCEPT);
64:     if (acceptHeader != null && !acceptHeader.isEmpty()) {
65:       winner = MimeParse.bestMatch(types, acceptHeader);
66:     }
67: 
68:     if (winner == null || winner.isEmpty()) {
69:       exchange.clientError(406);
70:     } else {
71:       exchange.getResponse().setHeader(HttpHeaders.Names.CONTENT_TYPE, winner);
72:       Runnable runnable = map.get(winner);
73:       runnable.run();
74:     }
75:   }
76: 
77: }
