40:  *
41:  * def baseDir = new PathBaseDirBuilder(new File("some/dir"))
42:  * def app = new ClosureBackedEmbeddedApplication(baseDir)
43:  *
44:  * app.handlers {
45:  *   get("someHandler") {
46:  *     render "someHandler"
47:  *   }
48:  *
49:  *   // Include the handlers defined in OtherHandlers
50:  *   handler chain(new OtherHandlers())
51:  * }
