328:     private void runOnCompletes() {
329:       Runnable onComplete = onCompletes.poll();
330:       while (onComplete != null) {
331:         try {
332:           onComplete.run();
333:         } catch (Exception e) {
334:           e.printStackTrace();
335:         } finally {
336:           onComplete = onCompletes.poll();
337:         }
338:       }
339:     }
