108:       }
109:     };
110: 
111:     @Override
112:     public <T> Promise<T> blocking(final Callable<T> blockingOperation) {
113:       return promise(new Action<Fulfiller<? super T>>() {
114:         @Override
115:         public void execute(final Fulfiller<? super T> fulfiller) throws Exception {
116:           final Execution execution = getExecution();
117:           ListenableFuture<T> future = blockingExecutor.submit(new BlockingOperation(execution));
118:           Futures.addCallback(future, new ComputeResume(fulfiller), computeExecutor);
119:         }
120: 
121:         class BlockingOperation implements Callable<T> {
122:           private final Execution execution;
123:           private Exception exception;
124:           private T result;
125: 
126:           public BlockingOperation(Execution execution) {
127:             this.execution = execution;
128:           }
129: 
130:           @Override
131:           public T call() throws Exception {
132:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<Execution>() {
133:               @Override
134:               public void execute(Execution execution) throws Exception {
135:                 try {
136:                   result = blockingOperation.call();
137:                 } catch (Exception e) {
138:                   exception = e;
139:                 }
140:               }
141:             });
142: 
143:             if (exception != null) {
144:               throw exception;
145:             } else {
146:               return result;
147:             }
148:           }
149:         }
