285:     }
286: 
287: 
288:     public void join(final Action<? super ratpack.exec.Execution> action) {
289:       segments.addFirst(new UserCodeSegment(action));
290:       waiting = false;
291:       tryDrain();
292:     }
293: 
294:     public void joinExecutionEnd(final Action<? super ratpack.exec.Execution> action) {
295:       segments.addLast(new UserCodeSegment(action));
296:       waiting = false;
297:       tryDrain();
298:     }
299: 
300:     public void continueExecutionAndWait(final Action<? super ratpack.exec.Execution> action) {
301:       segments.add(new UserCodeSegment(action));
302:       waiting = false;
303:       tryDrain();
304:       waiting = true;
305:     }
