307:     public void continueVia(final Runnable runnable) {
308:       segments.addFirst(new Runnable() {
309:         @Override
310:         public void run() {
311:           waiting = true;
312:           runnable.run();
313:         }
314:       });
315:     }
316: 
317:     private void tryDrain() {
318:       assertNotDone();
319:       if (!done && !waiting && !segments.isEmpty()) {
320:         if (active.compareAndSet(false, true)) {
