322:         }
323:       }
324:     }
325: 
326:     private void runOnCompletes() {
327:       Runnable onComplete = onCompletes.poll();
328:       while (onComplete != null) {
329:         try {
330:           onComplete.run();
331:         } catch (Exception e) {
332:           e.printStackTrace();
333:         } finally {
334:           onComplete = onCompletes.poll();
335:         }
336:       }
337:     }
338: 
339:     private void drain() {
340:       if (isManagedThread()) {
341:         executionHolder.set(this);
342:         try {
343:           Runnable segment = segments.poll();
344:           while (segment != null) {
345:             segment.run();
346:             if (waiting) { // the segment initiated an async op
347:               break;
348:             } else {
349:               segment = segments.poll();
350:               if (segment == null) { // not waiting and no more segments, we are done
351:                 done = true;
352:                 runOnCompletes();
353:               }
354:             }
355:           }
356:         } finally {
357:           executionHolder.remove();
358:           active.set(false);
359:         }
360:         if (waiting) {
361:           tryDrain();
362:         }
363:       } else {
364:         active.set(false);
365:         eventLoopGroup.submit(new Runnable() {
366:           @Override
367:           public void run() {
368:             tryDrain();
369:           }
370:         });
371:       }
372:     }
