374:     @Override
375:     public void onComplete(Runnable runnable) {
376:       assertNotDone();
377:       onCompletes.add(runnable);
378:     }
379: 
380:     private void assertNotDone() {
381:       if (done) {
382:         throw new ExecutionException("execution is complete");
383:       }
384:     }
