386:     public void intercept(final ExecInterceptor.ExecType execType, final List<ExecInterceptor> interceptors, final Action<? super Execution> action) throws Exception {
387:       new InterceptedOperation(execType, interceptors) {
388:         @Override
389:         protected void performOperation() throws Exception {
390:           action.execute(Execution.this);
391:         }
392:       }.run();
393:     }
