410:           } catch (ExecutionSegmentTerminationError e) {
411:             throw e.getCause();
412:           }
413:         } catch (final Throwable e) {
414:           segments.clear();
415:           segments.addFirst(new Runnable() {
416:             @Override
417:             public void run() {
418:               try {
419:                 errorHandler.execute(e);
420:               } catch (final Throwable e) {
421:                 segments.addFirst(new UserCodeSegment(new Action<ratpack.exec.Execution>() {
422:                   @Override
423:                   public void execute(ratpack.exec.Execution execution) throws Exception {
424:                     throw e;
425:                   }
426:                 }));
427:               }
428:             }
429:           });
430:         }
431:       }
432:     }
433:   }
