146:    *   <li><strong>2</strong> - max 2 at a time promises run in parallel</li>
147:    *   <li><strong>3</strong> - max 3 at a time promises run in parallel</li>
148:    *   <li><strong>n</strong> - max n at a time promises run in parallel</li>
149:    * </ul>
150:    */
151:   public HealthCheckHandler(int concurrencyLevel) {
152:     this(null, concurrencyLevel);
153:   }
154: 
155:   /**
156:    * Execute health check of the given name and given {@code concurrencyLevel}.
157:    *
158:    * @param healthCheckName the name of health check
159:    * @param concurrencyLevel the level of parallelism for health check promises execution. Define number of health checks (as promises) to be run in parallel.
160:    * <ul>
161:    *   <li><strong>0</strong> - infinite potential parallelism - up to the event loop number of threads</li>
162:    *   <li><strong>1</strong> - serial, promises run one by one in sequence</li>
163:    *   <li><strong>2</strong> - max 2 at a time promises run in parallel</li>
164:    *   <li><strong>3</strong> - max 3 at a time promises run in parallel</li>
165:    *   <li><strong>n</strong> - max n at a time promises run in parallel</li>
166:    * </ul>
167:    */
168:   protected HealthCheckHandler(String healthCheckName, int concurrencyLevel) {
169:     this.pathTokenName = healthCheckName;
170:     this.concurrencyLevel = concurrencyLevel;
171:   }
172: 
173:   /**
174:    * Get the level of parallelism in non-blocking health check execution.
175:    *
176:    * @return concurrency level as defined in {@link ratpack.health.HealthCheckHandler#HealthCheckHandler} constructor. Parameter {@code concurrencyLevel}.
177:    */
178:   public int getConcurrencyLevel() {
179:     return concurrencyLevel;
180:   }
181: 
182:   /**
183:    * Get assigned health check name. If defined health check of this name is executed.
184:    *
185:    * @return health check name to be executed
186:    */
187:   public String getName() {
188:     return pathTokenName;
189:   }
190: 
191:   /**
192:    * Run individual health check with the given name or all health checks.
193:    * The {@code concurrencyLevel} determines parallelism in health check execution.
194:    *
195:    * @param context request context and exec control as well
196:    * @throws Exception if anything goes wrong, exception will be implicitly passed to the context's {@link Context#error(Throwable)} method
197:    */
198:   @Override
199:   public void handle(Context context) throws Exception {
200:     if (pathTokenName != null && !"".equals(pathTokenName)) {
201:       handleByName(context, pathTokenName);
202:     } else {
203:       handleAll(context);
204:     }
205:   }
206: 
207:   private void handleByName(Context context, String name) throws Exception {
208:     if (name == null || "".equals(name)) {
209:       context.clientError(404);
210:       return;
211:     }
212:     Optional<ratpack.health.HealthCheck> hcheck = context.first(TypeToken.of(ratpack.health.HealthCheck.class), hc -> {
213:       if (hc.getName().equals(name)) {
214:         return hc;
215:       } else {
216:         return null;
217:       }
218:     });
219:     if (!hcheck.isPresent()) {
220:       context.clientError(404);
221:       return;
222:     }
223:     try {
224:       Promise<ratpack.health.HealthCheck.Result> promise = hcheck.get().check(context.getExecution().getControl());
225:       promise.onError(throwable -> {
226:         context.render(new HealthCheckResults(ImmutableSortedMap.<String, ratpack.health.HealthCheck.Result>of(hcheck.get().getName(), ratpack.health.HealthCheck.Result.unhealthy(throwable))));
227:       }).then(r -> {
228:         context.render(new HealthCheckResults(ImmutableSortedMap.<String, ratpack.health.HealthCheck.Result>of(hcheck.get().getName(), r)));
229:       });
230:     } catch (Exception ex) {
231:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, ratpack.health.HealthCheck.Result>of(hcheck.get().getName(), ratpack.health.HealthCheck.Result.unhealthy(ex))));
232:     }
233:   }
234: 
235:   private void handleAll(Context context) throws Exception {
236:     SortedMap<String, ratpack.health.HealthCheck.Result> hcheckResults = new ConcurrentSkipListMap<>();
237: 
238:     SortedMap<String, Promise<ratpack.health.HealthCheck.Result>> promises = new ConcurrentSkipListMap<>();
239:     context.getAll(ratpack.health.HealthCheck.class).forEach(hcheck -> {
240:       try {
241:         Promise<ratpack.health.HealthCheck.Result> promise = hcheck.check(context.getExecution().getControl());
242:         promises.put(hcheck.getName(), promise);
243:       } catch (Exception ex) {
244:         hcheckResults.put(hcheck.getName(), ratpack.health.HealthCheck.Result.unhealthy(ex));
245:       }
246:     });
247: 
248:     if (promises.size() == 0) {
249:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, ratpack.health.HealthCheck.Result>copyOfSorted(hcheckResults)));
250:       return;
251:     }
252: 
253:     context.promise(f -> {
254:       // execute promises in parallel based on the concurrencyLevel
255:       // count finished health checks. If all are done, render results
256:       AtomicInteger executedPromisesCountDown = new AtomicInteger(promises.size());
257:       // count health checks waiting for execution.
258:       AtomicInteger toExecPromisesCountDown = new AtomicInteger(promises.size());
259:       // collect health checks to execute in the next run. Used when concurrencyLevel > 1
260:       Map<String, Promise<ratpack.health.HealthCheck.Result>> toExecPromises = new ConcurrentHashMap<>();
261: 
262:       promises.forEach((name, p) -> {
263:         boolean execParallel = false;
264:         if (concurrencyLevel <= 0) {
265:           // execute all health checks in parallel
266:           execParallel = true;
267:         } else if (concurrencyLevel == 1) {
268:           // execute promise by promise, in sequence
269:           execParallel = false;
270:         } else {
271:           // collect promises into group of concurrencyLevel size or into group of last promises to execute
272:           toExecPromises.put(name, p);
273:           if (toExecPromisesCountDown.decrementAndGet() > 0 && toExecPromises.size() < concurrencyLevel) {
274:             return;
275:           }
276:           // execute promises in group in parallel
277:           execParallel = true;
278:         }
279: 
280:         if (toExecPromises.size() > 0) {
281:           // promise of immutable map of promises to execute, controls construction and their parallel execution while allows
282:           // safe freeing of toExecPromises map.
283:           context.promiseOf(ImmutableMap.<String, Promise<ratpack.health.HealthCheck.Result>>copyOf(toExecPromises)).then(map -> {
284:             // control finalization of parent promise
285:             AtomicInteger groupOfPromisesCountDown = new AtomicInteger(map.size());
286:             context.promise(f2 -> {
287:               map.forEach((name2, p2) -> {
288:                 // execute promise p2 and check end condition: either last promise in group or last promise globally
289:                 execPromiseWithEndCondition(context, name2, p2, f2, hcheckResults, groupOfPromisesCountDown, executedPromisesCountDown);
290:               });
291:             }).then(finish -> {
292:               if (finish == Boolean.TRUE) {
293:                 f.success(hcheckResults);
294:               }
295:             });
296:           });
297: 
298:           toExecPromises.clear();
299: 
300:         } else {
301:           if (execParallel) {
302:             // execute promise and if last promise globally, return health check results
303:             execPromiseWithEndResult(context, name, p, f, hcheckResults, executedPromisesCountDown);
304:           } else {
305:             context.promise(f2 -> {
306:               // execute promise p and check end condition: if last promise globally
307:               execPromiseWithEndCondition(context, name, p, f2, hcheckResults, null, executedPromisesCountDown);
308:             }).then(finish -> {
309:               if (finish == Boolean.TRUE) {
310:                 f.success(hcheckResults);
311:               }
312:             });
313:           }
314:         }
315:       });
316:     }).then(results -> {
317:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, ratpack.health.HealthCheck.Result>copyOfSorted(hcheckResults)));
318:     });
319:   }
320: 
321:   /**
322:    * Execute promise and if last ({@code executedPromisesCountDown} is 0) return sorted map of health check results.
323:    * @param context execution context
324:    * @param name health check name
325:    * @param promise health check promise with calculation to be run
326:    * @param fulfiller fulfiller of an asynchronous promise
327:    * @param hcheckResults sorted map of health check results
328:    * @param executedPromisesCountDown counter of executed promises (counts down)
329:    */
330:   private void execPromiseWithEndResult(
331:           Context context,
332:           String name,
333:           Promise<ratpack.health.HealthCheck.Result> promise,
334:           Fulfiller<Object> fulfiller,
335:           SortedMap<String, ratpack.health.HealthCheck.Result> hcheckResults,
336:           AtomicInteger executedPromisesCountDown) {
337: 
338:     context.exec().onComplete(execution -> {
339:       if (executedPromisesCountDown.decrementAndGet() == 0) {
340:         fulfiller.success(hcheckResults);
341:       }
342:     }).onError(throwable -> {
343:       hcheckResults.put(name, ratpack.health.HealthCheck.Result.unhealthy(throwable));
344:       if (executedPromisesCountDown.decrementAndGet() == 0) {
345:         fulfiller.success(hcheckResults);
346:       }
347:     }).start(execution -> {
348:       promise.then(r -> {
349:         hcheckResults.put(name, r);
350:       });
351:     });
352:   }
353: 
354:   /**
355:    * Execute promise and check end condition. Report Boolean as result.
356:    * End condition: finish outer promise if {@code groupOfPromisesCountDown} is given and its decremented value is 0 or
357:    * decremented {@code executedPromisesCountDown} is 0, return Boolean.TRUE if there is nothing to left to do, so if
358:    * {@code executedPromisesCountDown} is 0.
359:    * @param context execution context
360:    * @param name health check name
361:    * @param promise health check promise with calculation to be run
362:    * @param fulfiller fulfiller of an asynchronous promise
363:    * @param hcheckResults sorted map of health check results
364:    * @param groupOfPromisesCountDown counter of executed promises in the given group (counts down)
365:    * @param executedPromisesCountDown counter of executed promises (counts down)
366:    */
367:   private void execPromiseWithEndCondition(
368:           Context context,
369:           String name,
370:           Promise<ratpack.health.HealthCheck.Result> promise,
371:           Fulfiller<Object> fulfiller,
372:           SortedMap<String, ratpack.health.HealthCheck.Result> hcheckResults,
373:           AtomicInteger groupOfPromisesCountDown, AtomicInteger executedPromisesCountDown) {
374: 
375:     context.exec().onComplete(execution -> {
376:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
377:       if (groupOfPromisesCountDown != null) {
378:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
379:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
380:         }
381:       } else {
382:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
383:       }
384:     }).onError(throwable -> {
385:       hcheckResults.put(name, ratpack.health.HealthCheck.Result.unhealthy(throwable));
386:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
387:       if (groupOfPromisesCountDown != null) {
388:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
389:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
390:         }
391:       } else {
392:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
393:       }
394:     }).start(execution -> {
395:       promise.then(r -> {
396:         hcheckResults.put(name, r);
397:       });
398:     });
399:   }
400: }
