217:    * @return A handler that makes all Guice bound objects available to the handlers added to the {@link Chain} given to {@code chainConfigurer}.
218:    */
219:   public static Handler handler(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, final Action<? super Chain> chainConfigurer) throws Exception {
220:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), new InjectorHandlerTransformer(launchConfig, chainConfigurer));
221:   }
222: 
223:   /**
224:    * Creates a handler that can be used as the entry point for a Guice backed Ratpack app.
225:    * <p>
226:    * This is a lower level version of {@link #handler(ratpack.launch.LaunchConfig, com.google.inject.Injector, ratpack.func.Action, ratpack.func.Action)}
227:    * that supports a custom final {@link Handler} creation strategy.
228:    *
229:    * @param launchConfig The launch config of the server
230:    * @param parentInjector The injector to use as a parent of the injector to be created
231:    * @param moduleConfigurer The configurer of the {@link BindingsSpec} to back the created handler
232:    * @param injectorTransformer Takes the final {@link Injector} instance that was created from the modules and returns the {@link Handler} to use
233:    * @return A handler that makes all Guice bound objects available to the handlers added to the {@link Chain} given to {@code chainConfigurer}.
234:    */
235:   public static Handler handler(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, Function<? super Injector, ? extends Handler> injectorTransformer) throws Exception {
236:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), injectorTransformer);
237:   }
238: 
239:   /**
240:    * Creates a Ratpack {@link Registry} backed by the given {@link Injector} that will create objects via “just-in-time” binding.
241:    * <p>
242:    * The returned registry differs from the registry returned by {@link #registry(com.google.inject.Injector)} in that it may return objects that were not explicitly bound,
243:    * via Guice's “just-in-time” binding mechanism.
244:    * This only applies to the {@link Registry#get(Class)} and {@link Registry#maybeGet(Class)} (for all overloads).
245:    * All other methods do not perform any just in time bindings.
246:    *
247:    * @param injector The injector to back the registry
248:    * @return A registry that wraps the injector
249:    */
250:   public static Registry justInTimeRegistry(Injector injector) {
251:     return new JustInTimeInjectorRegistry(injector);
252:   }
253: 
254:   /**
