373:   protected void doNext(Context parentContext, final Registry registry, final int nextIndex, final Handler[] nextHandlers, Handler exhausted) {
374:     Context context;
375:     Handler handler;
376: 
377:     if (nextIndex >= nextHandlers.length) {
378:       context = parentContext;
379:       handler = exhausted;
380:     } else {
381:       handler = nextHandlers[nextIndex];
382:       context = createContext(registry, nextHandlers, nextIndex + 1, exhausted);
383:     }
384: 
385:     requestConstants.applicationConstants.contextThreadLocal.set(context);
386: 
387:     try {
388:       handler.handle(context);
389:     } catch (Exception e) {
390:       if (e instanceof HandlerException) {
391:         throw (HandlerException) e;
392:       } else {
393:         throw new HandlerException(context, e);
394:       }
395:     }
396:   }
