248:    *     ExecHarness.runSingle(e ->
249:    *       Promise.value("hello world")
250:    *         .to(RxRatpack::single)
251:    *         .map(String::toUpperCase)
252:    *         .subscribe(s -> value = s)
253:    *     );
254:    *
255:    *     assertEquals("HELLO WORLD", value);
256:    *   }
257:    * }
258:    * }</pre>
