322:   /**
323:    * Converts an {@link Observable} into a {@link Promise}, for all of the observable's items.
324:    * <p>
325:    * This method can be used to simply adapt an observable to a promise, but can also be used to bind an observable to the current execution.
326:    * It is sometimes more convenient to use {@link #promise(ObservableOnSubscribe)} over this method.
327:    * <p>
328:    * <pre class="java">{@code
329:    * import ratpack.rx2.RxRatpack;
330:    * import ratpack.test.exec.ExecHarness;
331:    * import io.reactivex.Observable;
332:    * import java.util.List;
333:    * import java.util.Arrays;
334:    * import static org.junit.Assert.assertEquals;
335:    *
336:    * public class Example {
