30: public class DefaultByMethodChain implements ByMethodChain {
31: 
32:   private final Exchange exchange;
33:   private final Map<String, Runnable> runnables = new LinkedHashMap<String, Runnable>(2);
34: 
35:   public DefaultByMethodChain(Exchange exchange) {
36:     this.exchange = exchange;
37:   }
38: 
39:   public ByMethodChain get(Runnable runnable) {
40:     return named("get", runnable);
41:   }
42: 
43:   public ByMethodChain post(Runnable runnable) {
44:     return named("post", runnable);
45:   }
46: 
47:   public ByMethodChain named(String methodName, Runnable runnable) {
48:     runnables.put(methodName.toLowerCase(), runnable);
49:     return this;
50:   }
51: 
52:   private static class ByMethodHandler implements Handler {
53:     private final Runnable runnable;
54:     private final String method;
55: 
56:     private ByMethodHandler(String method, Runnable runnable) {
57:       this.method = method;
58:       this.runnable = runnable;
59:     }
60: 
61:     public void handle(Exchange exchange) {
62:       if (exchange.getRequest().getMethod().name(method)) {
63:         runnable.run();
64:       } else {
65:         exchange.next();
66:       }
67:     }
68:   }
69: 
70:   public void call() {
71:     List<Handler> handlers = new ArrayList<Handler>(runnables.size());
72:     for (Map.Entry<String, Runnable> entry : runnables.entrySet()) {
73:       handlers.add(new ByMethodHandler(entry.getKey(), entry.getValue()));
74:     }
75:     handlers.add(new ClientErrorHandler(METHOD_NOT_ALLOWED.code()));
76:     exchange.next(handlers);
77:   }
78: 
79: }
